import type cytoscape from 'cytoscape';
import { byId, escapeHtml } from '../core/dom.js';
import { stripInlineMathText } from '../core/text.js';
import type { AppState, GraphNode, LineStyle, Point, Preferences } from '../types.js';
import type { GraphModel } from '../model/graph-model.js';

export interface SvgExportResult {
  svg: string;
  nodeCount: number;
  edgeCount: number;
  width: number;
  height: number;
}

interface SvgExportContent {
  nodes: cytoscape.NodeCollection;
  edges: cytoscape.EdgeCollection;
  accessibleTitle: string;
  accessibleDescription: string;
  exportNote: string;
  allowEmpty?: boolean;
  minimumWidth?: number;
}

export class SvgExporter {
  private readonly context = document.createElement('canvas').getContext('2d');
  private readonly fontFamily = 'Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  private static readonly logoDataUri = 'data:image/png;base64,';

  constructor(
    private readonly cy: cytoscape.Core,
    private readonly model: GraphModel,
    private readonly state: AppState,
    private readonly preferences: () => Preferences,
    private readonly nodeSequence: () => readonly string[] = () => []
  ) {}

  serializeVisible(): SvgExportResult | null {
    const visibleNodes = this.cy.nodes().not('.filter-hidden').filter((element) => element.style('display') !== 'none');
    const visibleEdges = this.cy.edges().not('.filter-hidden').filter((element) => {
      const edge = element as cytoscape.EdgeSingular;
      return edge.style('display') !== 'none'
        && !edge.source().hasClass('filter-hidden') && !edge.target().hasClass('filter-hidden');
    });
    const structureScale = this.state.layout === 'fields' ? 'field' : this.state.layout === 'domains' ? 'domain' : null;
    return this.serialize({
      nodes: visibleNodes,
      edges: visibleEdges,
      accessibleTitle: structureScale ? `${structureScale === 'field' ? 'Field' : 'Domain'} structure — ${this.model.data.meta.title}` : this.model.data.meta.title,
      accessibleDescription: structureScale
        ? `${this.model.data.meta.description} Exported with the visible concept graph dimmed beneath ${structureScale} centroids and directed aggregate relations.`
        : `${this.model.data.meta.description} Exported from the current visible graph.`,
      exportNote: structureScale
        ? `Current ${structureScale} structure overlay; aggregate arrow width represents directed relation count.`
        : 'Exported from the current visible graph; use the atlas site for the latest data and terms.'
    });
  }

  serializePrimaryDomain(domainId: string): SvgExportResult | null {
    const domain = this.model.data.domains[domainId];
    if (!domain) return null;
    const nodes = this.cy.nodes().filter((element) => this.model.nodeRecord.get(element.id())?.primaryDomain === domainId);
    const nodeIds = new Set(nodes.map((element) => element.id()));
    const edges = this.cy.edges().filter((element) => {
      const record = this.model.edgeRecord.get(element.id());
      return Boolean(record && !record.synthetic && nodeIds.has(record.source) && nodeIds.has(record.target));
    });
    return this.serialize({
      nodes,
      edges,
      accessibleTitle: `${domain.label} — ${this.model.data.meta.title}`,
      accessibleDescription: `${domain.label} domain export from ${this.model.data.meta.title}. It contains only nodes whose primary domain is ${domain.label}, with every recorded relation between those nodes.`,
      exportNote: nodes.length
        ? `${domain.label}: primary-domain nodes and all relations between them.`
        : `${domain.label}: no nodes currently use this as their primary domain.`,
      allowEmpty: true,
      minimumWidth: 720
    });
  }

  private serialize(content: SvgExportContent): SvgExportResult | null {
    const { nodes: visibleNodes, edges: visibleEdges, accessibleTitle, accessibleDescription, exportNote, allowEmpty = false, minimumWidth = 0 } = content;
    if (!visibleNodes.length && !allowEmpty) return null;

    const box = visibleNodes.length
      ? visibleNodes.boundingBox({ includeLabels: false, includeOverlays: false })
      : { x1: 0, y1: 0, w: 840, h: 180 };
    const margin = 90;
    const headerHeight = 68;
    const minX = box.x1 - margin;
    const minY = box.y1 - margin - headerHeight;
    const graphWidth = (box.w + margin * 2) * 0.5;
    const graphHeight = (box.h + margin * 2) * 0.5;
    const width = Math.max(minimumWidth, graphWidth);
    const height = headerHeight + graphHeight;
    const graphOriginX = minX;
    const graphOriginY = minY + headerHeight;
    const graphOriginalWidth = box.w + margin * 2;
    const graphOriginalHeight = box.h + margin * 2;
    const parts: string[] = [];
    const data = this.model.data;
    parts.push('<?xml version="1.0" encoding="UTF-8"?>');
    parts.push(`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${Math.ceil(width)}" height="${Math.ceil(height)}" viewBox="${minX} ${minY} ${width} ${height}" role="img" aria-labelledby="atlas-title atlas-desc">`);
    parts.push(`<title id="atlas-title">${escapeHtml(accessibleTitle)}</title>`);
    parts.push(`<desc id="atlas-desc">${escapeHtml(accessibleDescription)}</desc>`);
    parts.push('<metadata><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:cc="http://creativecommons.org/ns#"><rdf:Description rdf:about=""><dc:creator>Advay Mengle</dc:creator><dc:title>mAtlas - Atlas of Fundamental Concepts</dc:title><dc:rights>mAtlas - Copyright (c) 2026 Advay Mengle - https://atlas.madvay.com/</dc:rights><cc:license rdf:resource="https://creativecommons.org/licenses/by-sa/4.0/"/></rdf:Description></rdf:RDF></metadata>');
    parts.push('<defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="0.7" fill="#cbd5e1" opacity="0.55"/></pattern></defs>');
    parts.push(`<rect x="${minX}" y="${minY}" width="${width}" height="${height}" fill="#fbfcfe"/>`);
    parts.push(`<rect x="${minX}" y="${minY}" width="${width}" height="${headerHeight}" fill="#ffffff" opacity="0.93"/>`);
    parts.push(`<g transform="translate(${minX + 24} ${minY + 20})"><image href="${SvgExporter.logoDataUri}" width="48" height="48"/></g>`);
    parts.push(`<text x="${minX + 86}" y="${minY + 28}" font-family="${escapeHtml(this.fontFamily)}" font-size="20" font-weight="700" fill="#172033">Atlas of Fundamental Concepts</text>`);
    parts.push(`<text x="${minX + 86}" y="${minY + 46}" font-family="${escapeHtml(this.fontFamily)}" font-size="11" fill="#475569"><a href="https://atlas.madvay.com" xlink:href="https://atlas.madvay.com">https://atlas.madvay.com</a> · © 2026 Advay Mengle · <a href="https://creativecommons.org/licenses/by-sa/4.0/" xlink:href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a></text>`);
    parts.push(`<text x="${minX + 86}" y="${minY + 62}" font-family="${escapeHtml(this.fontFamily)}" font-size="9" fill="#64748b">${escapeHtml(exportNote)}</text>`);
    parts.push(`<g transform="translate(${graphOriginX} ${graphOriginY}) scale(0.5) translate(${-graphOriginX} ${-graphOriginY})">`);
    parts.push(`<rect x="${minX}" y="${minY + headerHeight}" width="${graphOriginalWidth}" height="${graphOriginalHeight}" fill="url(#grid)"/>`);

    visibleEdges.forEach((element) => {
      if (Number(element.data('semanticConnection')) === 1) {
        const sourceElement = element.source();
        const targetElement = element.target();
        const source = sourceElement.position();
        const target = targetElement.position();
        const dx = target.x - source.x;
        const dy = target.y - source.y;
        const length = Math.max(1, Math.hypot(dx, dy));
        const perpendicular = { x: -dy / length, y: dx / length };
        const distance = Number(element.data('curveDistance')) || 0;
        const control = {
          x: (source.x + target.x) / 2 + perpendicular.x * distance,
          y: (source.y + target.y) / 2 + perpendicular.y * distance
        };
        const sourceBorder = Number(sourceElement.data('borderWidth') ?? 0);
        const targetBorder = Number(targetElement.data('borderWidth') ?? 0);
        const start = this.rectangleBoundaryPoint(
          source, control,
          Number(sourceElement.data('nodeWidth')) / 2 + sourceBorder,
          Number(sourceElement.data('nodeHeight')) / 2 + sourceBorder
        );
        const end = this.rectangleBoundaryPoint(
          target, control,
          Number(targetElement.data('nodeWidth')) / 2 + targetBorder,
          Number(targetElement.data('nodeHeight')) / 2 + targetBorder
        );
        const selected = element.selected();
        const color = selected ? '#0f172a' : String(element.data('structureColor') ?? '#64748b');
        const strokeWidth = selected
          ? Number(element.data('selectedEdgeWidth') ?? element.data('edgeWidth') ?? 3)
          : Number(element.data('edgeWidth') ?? 3);
        const emphasized = element.hasClass('structure-connection-emphasis');
        const opacity = selected || emphasized ? 1 : 0.18;
        parts.push(`<path d="M ${start.x.toFixed(2)} ${start.y.toFixed(2)} Q ${control.x.toFixed(2)} ${control.y.toFixed(2)} ${end.x.toFixed(2)} ${end.y.toFixed(2)}" fill="none" stroke="${escapeHtml(color)}" stroke-width="${strokeWidth.toFixed(2)}" opacity="${opacity}"/>`);
        const tangentX = end.x - control.x;
        const tangentY = end.y - control.y;
        const tangentLength = Math.max(1, Math.hypot(tangentX, tangentY));
        const ux = tangentX / tangentLength;
        const uy = tangentY / tangentLength;
        const arrowSize = Number(element.data('arrowSize')) || strokeWidth * 1.7;
        const baseDistance = arrowSize * 1.25;
        const baseX = end.x - ux * baseDistance;
        const baseY = end.y - uy * baseDistance;
        parts.push(`<path d="M ${end.x.toFixed(2)} ${end.y.toFixed(2)} L ${(baseX - uy * arrowSize * 0.62).toFixed(2)} ${(baseY + ux * arrowSize * 0.62).toFixed(2)} L ${(baseX + uy * arrowSize * 0.62).toFixed(2)} ${(baseY - ux * arrowSize * 0.62).toFixed(2)} Z" fill="${escapeHtml(color)}" opacity="${opacity}"/>`);
        return;
      }
      const record = this.model.edgeRecord.get(element.id());
      if (!record) return;
      const sourceElement = element.source();
      const targetElement = element.target();
      const sourceRecord = this.model.nodeRecord.get(sourceElement.id());
      const targetRecord = this.model.nodeRecord.get(targetElement.id());
      if (!sourceRecord || !targetRecord) return;
      const source = sourceElement.position();
      const target = targetElement.position();
      const dx = target.x - source.x;
      const dy = target.y - source.y;
      const length = Math.max(1, Math.hypot(dx, dy));
      const perpendicular = { x: -dy / length, y: dx / length };
      const distance = Number(element.data('curveDistance')) || 0;
      const control = {
        x: (source.x + target.x) / 2 + perpendicular.x * distance,
        y: (source.y + target.y) / 2 + perpendicular.y * distance
      };
      const sourceHalf = sourceRecord.kind === 'junction' ? { w: 62, h: 33 } : { w: 86, h: 33 };
      const targetHalf = targetRecord.kind === 'junction' ? { w: 62, h: 33 } : { w: 86, h: 33 };
      const start = this.rectangleBoundaryPoint(source, control, sourceHalf.w, sourceHalf.h);
      const end = this.rectangleBoundaryPoint(target, control, targetHalf.w, targetHalf.h);
      const prerequisiteHighlighted = element.hasClass('prerequisite-highlight');
      const color = prerequisiteHighlighted ? '#7dd3fc' : data.edgeTypes[record.type]?.color ?? '#64748b';
      const dash = this.lineDash(record.synthetic ? 'dashed' : data.edgeTypes[record.type]?.lineStyle);
      const selected = element.selected();
      const strokeWidth = selected ? 4.5 : prerequisiteHighlighted ? 4 : record.synthetic ? 2.6 : 2.1;
      const edgeOpacity = prerequisiteHighlighted
        ? 1
        : element.hasClass('neighborhood-dim')
          ? 0.14
          : element.hasClass('dependency-context') && this.preferences().dimPrerequisites ? 0.46 : 1;
      parts.push(`<path d="M ${start.x.toFixed(2)} ${start.y.toFixed(2)} Q ${control.x.toFixed(2)} ${control.y.toFixed(2)} ${end.x.toFixed(2)} ${end.y.toFixed(2)}" fill="none" stroke="${escapeHtml(color)}" stroke-width="${strokeWidth}"${dash ? ` stroke-dasharray="${dash}"` : ''} opacity="${edgeOpacity}"/>`);
      const tangentX = end.x - control.x;
      const tangentY = end.y - control.y;
      const tangentLength = Math.max(1, Math.hypot(tangentX, tangentY));
      const ux = tangentX / tangentLength;
      const uy = tangentY / tangentLength;
      const baseX = end.x - ux * 11;
      const baseY = end.y - uy * 11;
      const leftX = baseX - uy * 5;
      const leftY = baseY + ux * 5;
      const rightX = baseX + uy * 5;
      const rightY = baseY - ux * 5;
      parts.push(`<path d="M ${end.x.toFixed(2)} ${end.y.toFixed(2)} L ${leftX.toFixed(2)} ${leftY.toFixed(2)} L ${rightX.toFixed(2)} ${rightY.toFixed(2)} Z" fill="${escapeHtml(color)}" opacity="${edgeOpacity}"/>`);

      if (!this.state.showEdgeLabels) return;
      const labelX = 0.25 * start.x + 0.5 * control.x + 0.25 * end.x;
      const labelY = 0.25 * start.y + 0.5 * control.y + 0.25 * end.y;
      const angle = Math.atan2(end.y - start.y, end.x - start.x) * 180 / Math.PI;
      const normalizedAngle = angle > 90 || angle < -90 ? angle + 180 : angle;
      const plainLabel = stripInlineMathText(record.label);
      const labelLines = this.wrappedLines(plainLabel, 9, record.synthetic ? 138 : 120);
      const lineHeight = 11;
      const fallbackWidth = Math.min(record.synthetic ? 148 : 130, Math.max(28,
        ...labelLines.map((line) => (this.context?.measureText(line).width ?? line.length * 5.4) + 10)));
      const fallbackHeight = labelLines.length * lineHeight + 6;
      parts.push(`<g transform="translate(${labelX.toFixed(2)} ${labelY.toFixed(2)}) rotate(${normalizedAngle.toFixed(2)})" opacity="${edgeOpacity}">`);
      parts.push('<g>');
      const labelFill = prerequisiteHighlighted ? '#e0f2fe' : record.synthetic ? '#fff7ed' : '#ffffff';
      const labelStroke = prerequisiteHighlighted ? '#7dd3fc' : record.synthetic ? '#fed7aa' : '#e2e8f0';
      const labelColor = prerequisiteHighlighted ? '#0c4a6e' : '#334155';
      parts.push(`<rect x="${(-fallbackWidth / 2).toFixed(2)}" y="${(-fallbackHeight / 2).toFixed(2)}" width="${fallbackWidth.toFixed(2)}" height="${fallbackHeight.toFixed(2)}" rx="3" fill="${labelFill}" fill-opacity="0.9" stroke="${labelStroke}" stroke-width="1"/>`);
      labelLines.forEach((line, index) => {
        const y = (index - (labelLines.length - 1) / 2) * lineHeight + 3;
        parts.push(`<text x="0" y="${y.toFixed(2)}" text-anchor="middle" font-family="${escapeHtml(this.fontFamily)}" font-size="9" font-weight="600" fill="${labelColor}">${escapeHtml(line)}</text>`);
      });
      parts.push('</g>');
      parts.push('</g>');
    });

    const sequenceIndex = new Map(this.nodeSequence().map((nodeId, index) => [nodeId, index + 1]));
    visibleNodes.forEach((element) => {
      if (Number(element.data('semanticGroup')) === 1) {
        const position = element.position();
        const selected = element.selected();
        const color = String(element.data('color') ?? '#64748b');
        const label = String(element.data('label') ?? '');
        const conceptCount = Number(element.data('conceptCount') ?? 0);
        parts.push(`<g><title>${escapeHtml(label)} — ${conceptCount} concept${conceptCount === 1 ? '' : 's'}</title>`);
        const lines = String(element.data('canvasLabel') ?? label).split('\n');
        const fontSize = Number(element.data('labelFontSize')) || 15;
        const lineHeight = fontSize * 1.06;
        const outlineWidth = selected
          ? Number(element.data('selectedTextOutlineWidth')) || Number(element.data('textOutlineWidth')) || 0
          : Number(element.data('textOutlineWidth')) || 0;
        lines.forEach((line, index) => {
          const textY = position.y + (index - (lines.length - 1) / 2) * lineHeight + fontSize * 0.34;
          parts.push(`<text x="${position.x.toFixed(2)}" y="${textY.toFixed(2)}" text-anchor="middle" font-family="${escapeHtml(this.fontFamily)}" font-size="${fontSize.toFixed(2)}" font-weight="800" fill="${escapeHtml(color)}" stroke="#ffffff" stroke-opacity="0.92" stroke-width="${outlineWidth.toFixed(2)}" stroke-linejoin="round" paint-order="stroke">${escapeHtml(line)}</text>`);
        });
        parts.push('</g>');
        return;
      }
      const record = this.model.nodeRecord.get(element.id());
      if (!record) return;
      const position = element.position();
      const isJunction = record.kind === 'junction';
      const nodeWidth = isJunction ? 116 : 164;
      const nodeHeight = 58;
      const x = position.x - nodeWidth / 2;
      const y = position.y - nodeHeight / 2;
      const isDependencyFaded = element.hasClass('dependency-faded');
      const prerequisiteHighlighted = element.hasClass('prerequisite-highlight');
      const structureSource = element.hasClass('structure-source-node');
      const opacity = structureSource
        ? 0.1
        : prerequisiteHighlighted ? 1 : element.hasClass('neighborhood-dim') ? 0.46 : 1;
      const selected = structureSource ? false : element.selected();
      const emphasized = element.hasClass('neighborhood-emphasis');
      const searchMatch = element.hasClass('search-match');
      const borderColor = selected ? '#0f172a' : searchMatch ? '#facc15' : prerequisiteHighlighted ? '#38bdf8' : emphasized ? '#f59e0b' : isJunction ? '#b45309' : '#ffffff';
      const borderWidth = selected || searchMatch ? 5 : prerequisiteHighlighted || emphasized ? 4 : isJunction ? 3 : 2;
      const linkHref = record.kind === 'structure'
        ? `https://atlas.madvay.com/concepts/${encodeURIComponent(record.id)}/`
        : `https://atlas.madvay.com/?node=${encodeURIComponent(record.id)}`;
      if (!structureSource) parts.push(`<a href="${linkHref}" xlink:href="${linkHref}" target="_blank" rel="noopener">`);
      if (isJunction) {
        const backgroundOpacity = prerequisiteHighlighted ? 1 : isDependencyFaded && this.preferences().dimPrerequisites ? 0.46 : 1;
        const fill = prerequisiteHighlighted ? '#bae6fd' : '#fff7ed';
        parts.push(`<rect x="${x}" y="${y}" width="${nodeWidth}" height="${nodeHeight}" rx="8" fill="${fill}" stroke="${borderColor}" stroke-width="${borderWidth}" stroke-dasharray="8 5" fill-opacity="${backgroundOpacity}" opacity="${opacity}"/>`);
      } else {
        const fill = prerequisiteHighlighted ? '#bae6fd' : data.domains[record.primaryDomain]?.color ?? '#64748b';
        const backgroundOpacity = prerequisiteHighlighted ? 1 : isDependencyFaded && this.preferences().dimPrerequisites ? 0.46 : 0.92;
        parts.push(`<rect x="${x}" y="${y}" width="${nodeWidth}" height="${nodeHeight}" rx="8" fill="${escapeHtml(fill)}" fill-opacity="${backgroundOpacity}" stroke="${borderColor}" stroke-width="${borderWidth}" opacity="${opacity}"/>`);
        const additionalDomains = structureSource ? [] : this.model.nodeDomainIds(record).slice(1);
        if (additionalDomains.length) {
          const markerWidth = additionalDomains.length * 12 - 3;
          const markerX = x + nodeWidth - markerWidth;
          const markerY = y + nodeHeight - 9;
          additionalDomains.forEach((domainId, index) => {
            const color = data.domains[domainId]?.color ?? '#64748b';
            parts.push(`<circle cx="${markerX + 4.5 + index * 12}" cy="${markerY + 4.5}" r="4.5" fill="${escapeHtml(color)}" opacity="${opacity}"/>`);
          });
        }
      }
      const label = structureSource ? '' : stripInlineMathText(record.label);
      const fontSize = Math.min(16, this.fittingLabelCap(record, label));
      const lines = label ? this.wrappedLines(label, fontSize, isJunction ? 92 : 144) : [];
      const lineHeight = fontSize * 1.16;
      const textColor = prerequisiteHighlighted ? '#0c4a6e' : isJunction ? '#7c2d12' : '#ffffff';
      lines.forEach((line, index) => {
        const textY = position.y + (index - (lines.length - 1) / 2) * lineHeight + fontSize * 0.34;
        parts.push(`<text x="${position.x}" y="${textY.toFixed(2)}" text-anchor="middle" font-family="${escapeHtml(this.fontFamily)}" font-size="${fontSize.toFixed(2)}" font-weight="600" fill="${textColor}" opacity="${opacity}">${escapeHtml(line)}</text>`);
      });
      const stepNumber = structureSource ? undefined : sequenceIndex.get(record.id);
      if (stepNumber !== undefined) {
        parts.push(`<circle cx="${x}" cy="${y + nodeHeight}" r="10" fill="#ffffff" stroke="#0f172a" stroke-width="2" opacity="${opacity}"/>`);
        parts.push(`<text x="${x}" y="${(y + nodeHeight + 3.5).toFixed(2)}" text-anchor="middle" font-family="${escapeHtml(this.fontFamily)}" font-size="10" font-weight="800" fill="#0f172a" opacity="${opacity}">${stepNumber}</text>`);
      }
      if (!structureSource) parts.push('</a>');
    });

    parts.push('</g>');
    parts.push('</svg>');
    return {
      svg: parts.join(''),
      nodeCount: visibleNodes.length,
      edgeCount: visibleEdges.length,
      width: Math.ceil(width),
      height: Math.ceil(height)
    };
  }

  exportVisible(): void {
    const result = this.serializeVisible();
    if (!result) return;
    const blob = new Blob([result.svg], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 19).replaceAll(':', '-');
    link.href = url;
    link.download = `atlas-of-fundamental-concepts-${stamp}.svg`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1200);
    byId('status').textContent = `Exported ${result.nodeCount} nodes and ${result.edgeCount} edges as SVG.`;
  }

  private lineDash(lineStyle: LineStyle | undefined): string {
    if (lineStyle === 'dashed') return '10 7';
    if (lineStyle === 'dotted') return '2 6';
    return '';
  }

  private wrappedLines(text: string, fontSize: number, maxWidth: number): string[] {
    if (!this.context) return [text];
    this.context.font = `600 ${fontSize}px ${this.fontFamily}`;
    const result: string[] = [];
    for (const explicit of text.split('\n')) {
      const words = explicit.trim().split(/\s+/).filter(Boolean);
      if (!words.length) {
        result.push('');
        continue;
      }
      let line = '';
      for (const word of words) {
        const candidate = line ? `${line} ${word}` : word;
        if (!line || this.context.measureText(candidate).width <= maxWidth) line = candidate;
        else {
          result.push(line);
          line = word;
        }
      }
      if (line) result.push(line);
    }
    return result;
  }

  private fittingLabelCap(node: GraphNode, label: string): number {
    const maxWidth = node.kind === 'junction' ? 92 : 144;
    const maxHeight = node.kind === 'junction' ? 54 : 52;
    const minSize = node.kind === 'junction' ? 9.5 : 13;
    const maxSize = node.kind === 'junction' ? 28 : 44;
    let low = minSize;
    let high = maxSize;
    for (let iteration = 0; iteration < 12; iteration += 1) {
      const midpoint = (low + high) / 2;
      const lines = this.wrappedLines(label, midpoint, maxWidth);
      const widest = Math.max(0, ...lines.map((line) => this.context?.measureText(line).width ?? line.length * midpoint * 0.6));
      if (widest <= maxWidth && lines.length * midpoint * 1.16 <= maxHeight) low = midpoint;
      else high = midpoint;
    }
    return Math.max(minSize, Math.floor(low * 4) / 4 - 1);
  }

  private rectangleBoundaryPoint(center: Point, toward: Point, halfWidth: number, halfHeight: number): Point {
    const dx = toward.x - center.x;
    const dy = toward.y - center.y;
    const scaleX = Math.abs(dx) > 1e-6 ? halfWidth / Math.abs(dx) : Number.POSITIVE_INFINITY;
    const scaleY = Math.abs(dy) > 1e-6 ? halfHeight / Math.abs(dy) : Number.POSITIVE_INFINITY;
    const scale = Math.min(scaleX, scaleY);
    return { x: center.x + dx * scale, y: center.y + dy * scale };
  }
}
